"""The schemas of the two LLM calls of the MPVI pipeline (design plan 8, D4 addendum), as Pydantic models.

Both calls use enforced structured output: the provider is given the JSON schema of the model (`Plan.model_json_schema()`, `Labels.model_json_schema()`) through its native
structured-output support (or through Instructor as a wrapper: `response_model=Plan`), and the reply is validated again here with `model_validate`, so a reply that does not fit stops
the plan before it starts. The provider itself is PENDING (design plan 8).

    Plan      the planning call's reply: exactly the paper's segment fields (Appendices C.1 and D): {"task_name", "segments": [{"type", "description", "completion_criteria", "target"}]}
    Labels    the labeling (post-processing) call's reply: for each manipulation segment its primitive (pick, place or other) and the object phrases it refers to, each with a role

Contents:
    Segment, Plan: the planning schema.
    Primitive, Role, ObjectPhrase, SegmentLabel, Labels: the labeling schema.
"""

from enum import Enum
from typing import Literal, Optional

from pydantic import BaseModel, ConfigDict, Field, model_validator


class Segment(BaseModel):
    """One segment of the plan, exactly the paper's fields."""

    model_config = ConfigDict(extra="forbid")

    type: Literal["navigation", "manipulation"]
    description: str = Field(min_length=1)
    completion_criteria: str = Field(min_length=1)
    target: Optional[str] = None

    @model_validator(mode="after")
    def _target_for_navigation_only(self):
        if (self.type == "navigation") != (self.target is not None):
            raise ValueError("the target is given for navigation segments only")
        return self


class Plan(BaseModel):
    """The planner's reply: the task name and at least one segment."""

    model_config = ConfigDict(extra="forbid")

    task_name: str = Field(min_length=1)
    segments: list[Segment] = Field(min_length=1)


class Primitive(str, Enum):
    """What a manipulation segment maps to: the scripted skills pick and place, or "other" (no skill: the step stops when it starts)."""

    pick = "pick"
    place = "place"
    other = "other"


class Role(str, Enum):
    """What an object phrase is in its step: the object acted on, or where it goes (the place's surface)."""

    manipulated = "manipulated"
    destination = "destination"


class ObjectPhrase(BaseModel):
    """An object phrase as written in the step's description, with its role."""

    model_config = ConfigDict(extra="forbid")

    phrase: str = Field(min_length=1)
    role: Role


class SegmentLabel(BaseModel):
    """The labels of one manipulation segment."""

    model_config = ConfigDict(extra="forbid")

    index: int = Field(ge=0)
    primitive: Primitive
    objects: list[ObjectPhrase]


class Labels(BaseModel):
    """The labeling call's reply: one SegmentLabel per manipulation segment."""

    model_config = ConfigDict(extra="forbid")

    labels: list[SegmentLabel]
